for name, spec in DATA.items():
    path=Path(name); original=path.read_bytes()
    assert hashlib.sha256(original).hexdigest()==spec['before'], 'Source changed: '+name
    lines=original.decode().splitlines(keepends=True)
    for start,end,text in reversed(spec['edits']): lines[start:end]=[text]
    result=''.join(lines).encode()
    assert hashlib.sha256(result).hexdigest()==spec['after'], 'Integration mismatch: '+name
    path.write_bytes(result)
print('Integrated six exact source edits; no other existing file changed.')
